    match c {
        'o' => {
            // Check if it's a half note 'o|' or whole note 'o'
            chars.next(); // consume 'o'
            if chars.peek() == Some(&'|') {
                beats.push(2);
                chars.next(); // consume '|'
            } else {
                beats.push(4);
            }
        },
        '.' => {
            // It's a quarter note '.|'
            chars.next(); // consume '.'
            if chars.peek() == Some(&'|') {
                beats.push(1);
                chars.next(); // consume '|'
            } else {
                // Invalid format, but per problem description we assume valid input
                beats.push(0);
            }
        },
        _ => {
            // Skip spaces or any other characters
            chars.next();
        }
    }
}

